   452  KArchiveDirectory *KArchivePrivate::findOrCreate(const QString &path, int recursionCounter)
   453  {
   454      // Check we're not in a path that is ultra deep, this is most probably fine since PATH_MAX on Linux
   455      // is defined as 4096, so even on /a/a/a/a/a/a 2500 recursions puts us over that limit
   456      // an ultra deep recursion will makes us crash due to not enough stack. Tests show that 1MB stack
   457      // (default on Linux seems to be 8MB) gives us up to around 4000 recursions
   458      if (recursionCounter > 2500) {
   459          qCWarning(KArchiveLog) << "path recursion limit exceeded, bailing out";
   460          return nullptr;
   461      }
   462      //qCDebug(KArchiveLog) << path;
   463      if (path.isEmpty() || path == QLatin1String("/") || path == QLatin1String(".")) { // root dir => found
   464          //qCDebug(KArchiveLog) << "returning rootdir";
   465          return q->rootDir();
   466      }
   467      // Important note : for tar files containing absolute paths
   468      // (i.e. beginning with "/"), this means the leading "/" will
   469      // be removed (no KDirectory for it), which is exactly the way
   470      // the "tar" program works (though it displays a warning about it)
   471      // See also KArchiveDirectory::entry().
   472
   473      // Already created ? => found
   474      const KArchiveEntry *ent = q->rootDir()->entry(path);
   475      if (ent) {
   476          if (ent->isDirectory())
   477              //qCDebug(KArchiveLog) << "found it";
   478          {
   479              const KArchiveDirectory *dir = static_cast<const KArchiveDirectory *>(ent);
   480              return const_cast<KArchiveDirectory *>(dir);
   481          } else {
   482              const KArchiveFile *file = static_cast<const KArchiveFile *>(ent);
   483              if (file->size() > 0) {
   484                  qCWarning(KArchiveLog) << path << "is normal file, but there are file paths in the archive assuming it is a directory, bailing out";
   485                  return nullptr;
   486              }
   487
   488              qCDebug(KArchiveLog) << path << " is an empty file, assuming it is actually a directory and replacing";
   489              KArchiveEntry *myEntry = const_cast<KArchiveEntry*>(ent);
   490              q->rootDir()->removeEntry(myEntry);
   491              delete myEntry;
   492          }
   493      }
   494
   495      // Otherwise go up and try again
   496      int pos = path.lastIndexOf(QLatin1Char('/'));
   497      KArchiveDirectory *parent;
   498      QString dirname;
   499      if (pos == -1) { // no more slash => create in root dir
   500          parent =  q->rootDir();
   501          dirname = path;
   502      } else {
   503          QString left = path.left(pos);
   504          dirname = path.mid(pos + 1);
   505          parent = findOrCreate(left, recursionCounter + 1);   // recursive call... until we find an existing dir.
   506      }
   507
   508      if (!parent) {
   509          return nullptr;
   510      }
   511
   512      //qCDebug(KArchiveLog) << "found parent " << parent->name() << " adding " << dirname << " to ensure " << path;
   513      // Found -> add the missing piece
   514      KArchiveDirectory *e = new KArchiveDirectory(q, dirname, rootDir->permissions(),
   515                                                   rootDir->date(), rootDir->user(),
   516                                                   rootDir->group(), QString());
   517      if (parent->addEntryV2(e)) {
   518          return e; // now a directory to <path> exists
   519      } else {
   520          return nullptr;
   521      }
   522  }
