   829  bool KZip::closeArchive()
   830  {
   831      if (!(mode() & QIODevice::WriteOnly)) {
   832          //qCDebug(KArchiveLog) << "readonly";
   833          return true;
   834      }
   835
   836      //ReadWrite or WriteOnly
   837      //write all central dir file entries
   838
   839      // to be written at the end of the file...
   840      char buffer[22]; // first used for 12, then for 22 at the end
   841      uLong crc = crc32(0L, nullptr, 0);
   842
   843      qint64 centraldiroffset = device()->pos();
   844      //qCDebug(KArchiveLog) << "closearchive: centraldiroffset: " << centraldiroffset;
   845      qint64 atbackup = centraldiroffset;
   846      QMutableListIterator<KZipFileEntry *> it(d->m_fileList);
   847
   848      while (it.hasNext()) {
   849          //set crc and compressed size in each local file header
   850          it.next();
   851          if (!device()->seek(it.value()->headerStart() + 14)) {
   852              setErrorString(
   853                  tr("Could not seek to next file header: %1")
   854                  .arg(device()->errorString()));
   855              return false;
   856          }
   857          //qCDebug(KArchiveLog) << "closearchive setcrcandcsize: fileName:"
   858          //    << it.current()->path()
   859          //    << "encoding:" << it.current()->encoding();
   860
   861          uLong mycrc = it.value()->crc32();
   862          buffer[0] = char(mycrc); // crc checksum, at headerStart+14
   863          buffer[1] = char(mycrc >> 8);
   864          buffer[2] = char(mycrc >> 16);
   865          buffer[3] = char(mycrc >> 24);
   866
   867          int mysize1 = it.value()->compressedSize();
   868          buffer[4] = char(mysize1); // compressed file size, at headerStart+18
   869          buffer[5] = char(mysize1 >> 8);
   870          buffer[6] = char(mysize1 >> 16);
   871          buffer[7] = char(mysize1 >> 24);
   872
   873          int myusize = it.value()->size();
   874          buffer[8] = char(myusize); // uncompressed file size, at headerStart+22
   875          buffer[9] = char(myusize >> 8);
